/** Get up to 30 demos for a given niche slug. */
export function getDemosForNiche(nicheId: string): VideoDemo[] {
  const slugs = NICHE_DEMO_SLUGS[nicheId] || [];
  const seen = new Set<string>();
  const out: VideoDemo[] = [];
  for (const d of ALL_DEMOS) {
    if (slugs.includes(d.slug) && !seen.has(d.slug)) {
      seen.add(d.slug);
      out.push(d);
    }
  }
  return out;
}

export const NICHE_IDS = Object.keys(NICHE_DEMO_SLUGS);